// Auto-generated Western theme visual assets (textures & cutouts)
import { ImageAsset, Node, Sprite, SpriteFrame, Texture2D, assetManager } from "cc";

export const WEST_TEXTURES = {
    /** 西部黄昏赛马场全景背景图 (9:16) */
    BG_RANCH: "data:image/jpeg;base64,",
    /** 美漫写实牛仔骑手人物立绘 (3:4) */
    /** 柯尔特特级骑师 / 老牛仔·亚瑟 头像立绘 (3:4) */
    JOCKEY_ARTHUR: "data:image/jpeg;base64,",

    /** 比利小子 · 闪电鞭 头像立绘 (3:4) */
    JOCKEY_BILLY: "data:image/jpeg;base64,",

    /** 安妮·奥克利 · 荒野神鹰女骑手 头像立绘 (3:4) */
    JOCKEY_ANNIE: "data:image/jpeg;base64,",

    JOCKEY_CHAR: "data:image/jpeg;base64,",
    /** 镀金马蹄星徽深红火漆印章 (1:1) */
    WAX_SEAL: "data:image/jpeg;base64,",
};

/**
 * 将西部风格切图安全应用到指定节点上的 Sprite 组件
 */
const spriteFrameCache = new Map<string, SpriteFrame>();

/**
 * 预加载并内存缓存所有西部切图资源，确保页面切换时 100% 同步挂载，彻底消除闪烁
 */
export function preloadWestAssets(onComplete?: () => void): void {
    const urls = Object.values(WEST_TEXTURES);
    let remaining = urls.length;
    if (remaining === 0) {
        onComplete?.();
        return;
    }
    const doneOne = () => {
        remaining--;
        if (remaining <= 0) {
            onComplete?.();
        }
    };
    for (const url of urls) {
        if (spriteFrameCache.has(url)) {
            doneOne();
            continue;
        }
        if (typeof Image !== "undefined") {
            const img = new Image();
            img.crossOrigin = "anonymous";
            img.onload = () => {
                const imageAsset = new ImageAsset(img);
                const texture = new Texture2D();
                texture.image = imageAsset;
                const spriteFrame = new SpriteFrame();
                spriteFrame.texture = texture;
                spriteFrameCache.set(url, spriteFrame);
                doneOne();
            };
            img.onerror = doneOne;
            img.src = url;
        } else {
            assetManager.loadRemote<ImageAsset>(url, (err, imageAsset) => {
                if (!err && imageAsset) {
                    const texture = new Texture2D();
                    texture.image = imageAsset;
                    const spriteFrame = new SpriteFrame();
                    spriteFrame.texture = texture;
                    spriteFrameCache.set(url, spriteFrame);
                }
                doneOne();
            });
        }
    }
}

/**
 * 将西部风格切图安全应用到指定节点上的 Sprite 组件（支持 0 延迟同步内存缓存）
 */
export function applyWestTexture(
    targetNode: Node,
    dataUri: string,
    sizeMode: number = 0,
    onLoaded?: () => void
): void {
    if (!targetNode || !targetNode.isValid) return;

    // 1. 若内存缓存命中，同步立刻赋值，消除任何异步黑屏和重新渲染闪烁！
    const cached = spriteFrameCache.get(dataUri);
    if (cached) {
        const sp = targetNode.getComponent(Sprite) || targetNode.addComponent(Sprite);
        sp.sizeMode = sizeMode;
        sp.spriteFrame = cached;
        if (onLoaded) onLoaded();
        return;
    }

    // 2. 首次未命中时走异步加载并回填缓存
    if (typeof Image !== "undefined") {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => {
            if (!targetNode.isValid) return;
            const imageAsset = new ImageAsset(img);
            const texture = new Texture2D();
            texture.image = imageAsset;
            const spriteFrame = new SpriteFrame();
            spriteFrame.texture = texture;
            spriteFrameCache.set(dataUri, spriteFrame);

            const sp = targetNode.getComponent(Sprite) || targetNode.addComponent(Sprite);
            sp.sizeMode = sizeMode;
            sp.spriteFrame = spriteFrame;
            if (onLoaded) onLoaded();
        };
        img.src = dataUri;
    } else {
        assetManager.loadRemote<ImageAsset>(dataUri, (err, imageAsset) => {
            if (!err && imageAsset && targetNode.isValid) {
                const texture = new Texture2D();
                texture.image = imageAsset;
                const spriteFrame = new SpriteFrame();
                spriteFrame.texture = texture;
                spriteFrameCache.set(dataUri, spriteFrame);

                const sp = targetNode.getComponent(Sprite) || targetNode.addComponent(Sprite);
                sp.sizeMode = sizeMode;
                sp.spriteFrame = spriteFrame;
                if (onLoaded) onLoaded();
            }
        });
    }
}

