/** 动态优先从服务端下发马匹快照中解析马匹名称、彩衣与跑法特性 */
export function getHorseVisualMeta(horseNo: number, dynamicHorse?: any): WestHorseMeta {
    const defaultMeta = WEST_HORSES_META[horseNo] || WEST_HORSES_META[((horseNo - 1) % 6) + 1] || {
        no: horseNo,
        nameZh: `赛驹 ${horseNo}号`,
        nameEn: `Horse #${horseNo}`,
        silkName: "经典彩衣",
        silkDesc: "Classic Jockey Silks",
        trait: "全地形耐力兼备"
    };

    if (dynamicHorse) {
        const nameZh = dynamicHorse.horseNameZhSnapshot || dynamicHorse.nameZh || dynamicHorse.horseNameZh || defaultMeta.nameZh;
        const nameEn = dynamicHorse.horseNameEnSnapshot || dynamicHorse.nameEn || dynamicHorse.horseNameEn || defaultMeta.nameEn;
        const trait = dynamicHorse.runningStyle
            ? `跑法: ${dynamicHorse.runningStyle}`
            : (dynamicHorse.trait || defaultMeta.trait);
        return {
            no: horseNo,
            nameZh,
            nameEn,
            silkName: defaultMeta.silkName,
            silkDesc: defaultMeta.silkDesc,
            trait
        };
    }

    return defaultMeta;
}

